impl Solution {
    pub fn longest_mountain(arr: Vec<i32>) -> i32 {
        let mut max_len = 0;
        let mut n = arr.len();
        if n < 3 {
            return 0;
        }

        let mut i = 1;
        while i < n - 1 {
            let mut up = 0;
            let mut down = 0;

            // Check if current position is a peak
            if arr[i] > arr[i - 1] && arr[i] > arr[i + 1] {
                // Count the increasing sequence
                while i > 0 && arr[i] > arr[i - 1] {
                    up += 1;
                    i -= 1;
                }

                // Count the decreasing sequence
                while i < n - 1 && arr[i] > arr[i + 1] {
                    down += 1;
                    i += 1;
                }

                // Total length of the mountain
                let len = up + down + 1;
                if len > max_len {
                    max_len = len;
                }
            }
            i += 1;
        }

        max_len as i32
    }
}

